import { createCarousel, type CarouselRole } from "@cssints/headless";
import type { JSX } from "@solidjs/web";
import * as css from "cssints" with { type: "cssints" };
import { createEffect, For, merge } from "solid-js";

import { t } from "./theme.ts" with { type: "cssints" };

export interface CarouselProps {
  /**
   * The slides, in order. Their number is read once, when the primitive is created: a page that adds a slide makes a new
   * carousel (the slide ids and the "1 of 5" labels are made from it).
   */
  readonly slides: ReadonlyArray<JSX.Element>;
  /** The accessible name of the carousel; ignored while `labelledBy` names it. @default "Carousel" */
  readonly label?: string | undefined;
  /** The id of the heading that names the carousel, when the page has one in sight. */
  readonly labelledBy?: string | undefined;
  /** The landmark wrapper: a named `region` is one a reader can jump to. @default "region" */
  readonly role?: CarouselRole;
  /** Shown slide at mount (uncontrolled). @default 0 */
  readonly defaultIndex?: number | undefined;
  /** Controlled: the host owns the shown slide and this is the only thing that changes it. */
  readonly value?: number | undefined;
  /** A request to show a slide: uncontrolled it is accepted, controlled the host may ignore it. */
  readonly onValueChange?: ((index: number) => void) | undefined;
  /** The line under the carousel; left out, the keys and the swipe in one sentence. */
  readonly hint?: string | undefined;
  readonly class?: string | undefined;
}

const DEFAULT_HINT =
  "Use the previous and next buttons, or the arrow keys when a slide has focus; on a touch screen, swipe.";

// The frame is the surface: the track and the control row sit on it, and the radius and the border are the kit's.
const frameClass = css.cn(
  css.display("grid"),
  css.gap(t.space._2),
  css.padding(t.space._2),
  css.boxSizing("border-box"),
  css.color(t.color.text),
  css.bg(t.color.surface),
  css.border("1px solid", t.color.border),
  css.borderRadius(t.radius.xl),
);

// The primitive hides every slide but the current one (`hidden`), so the track is a stack, not a scroll-snap strip: all
// slides share one grid cell and only the current one is displayed. The skin must not translate the track or turn the
// slides into a row, or a hidden slide would be reachable and the slide labels would stop matching what is on screen.
const trackClass = css.cn(
  css.display("grid"),
  css.overflow("hidden"),
  css.borderRadius(t.radius.lg),
  css.bg(t.color.page),
  // the swipe is the skin's horizontal gesture, so the browser keeps the vertical pan
  css.touchAction("pan-y"),
);

const slideClass = css.cn(css.gridArea("1 / 1"), css.minWidth("0"));

// The enter is the skin's, and only for a reader who allows motion: the active slide is displayed again on every change, so
// the animation restarts with it. There is no transition on the track itself.
const enter = css.keyframes({
  from: css.cn(css.opacity(0), css.transform("translateX(12px)")),
  to: css.cn(css.opacity(1), css.transform("none")),
});

const slideMotion = css.media("(prefers-reduced-motion: no-preference)")(
  css.animation(enter, "220ms", "ease-out"),
);

const barClass = css.cn(
  css.display("flex"),
  css.alignItems("center"),
  css.justifyContent("space-between"),
  css.gap(t.space._2),
  css.padding("0", t.space._1, t.space._1),
);

const controlClass = css.cn(
  css.appearance("none"),
  css.display("inline-flex"),
  css.alignItems("center"),
  css.justifyContent("center"),
  css.width(t.space._7),
  css.height(t.space._7),
  css.margin("0"),
  css.padding("0"),
  css.border("1px solid", t.color.border),
  css.borderRadius("999px"),
  css.bg(t.color.buttonBackground),
  css.color(t.color.text),
  css.fontSize(t.font.sizeLg),
  css.lineHeight(1),
  css.cursor("pointer"),
  css.hover(css.bg(t.color.buttonBackgroundPressed), css.borderColor(t.color.borderHover)),
  css.focusVisible(css.outline("2px solid", t.color.focusRing), css.outlineOffset("2px")),
);

const indicatorClass = css.cn(
  css.display("flex"),
  css.alignItems("center"),
  css.justifyContent("center"),
  css.gap(t.space._1),
);

// A dot is the visible 8 px mark inside a 24 px button: the pointer target is the WCAG 2.2 minimum, the mark is the
// indicator. The active dot reads `aria-current`, the state the button announces.
const dotClass = css.cn(
  css.appearance("none"),
  css.display("inline-flex"),
  css.alignItems("center"),
  css.justifyContent("center"),
  css.width(t.space._6),
  css.height(t.space._6),
  css.padding("0"),
  css.border("none"),
  css.borderRadius("999px"),
  css.bg("transparent"),
  css.cursor("pointer"),
  css.focusVisible(css.outline("2px solid", t.color.focusRing), css.outlineOffset("2px")),
);

const dotMarkClass = css.cn(
  css.width(t.space._2),
  css.height(t.space._2),
  css.borderRadius("999px"),
  css.border("1px solid", t.color.border),
  css.bg(t.color.surface),
);

const dotMarkActiveClass = css.cn(
  css.bg(t.color.highlight),
  css.borderColor(t.color.highlight),
);

const countClass = css.cn(
  css.minWidth(t.space._10),
  css.textAlign("center"),
  css.fontSize(t.font.sizeSm),
  css.fontVariantNumeric("tabular-nums"),
  css.color(t.color.muted),
);

const hintClass = css.cn(
  css.margin("0"),
  css.padding("0", t.space._2, t.space._1),
  css.fontSize(t.font.sizeSm),
  css.color(t.color.muted),
);

/** A swipe past this many px is a slide change; below it the pointer was a tap or an accidental drag. */
const SWIPE_THRESHOLD = 40;

/**
 * A carousel, styled: `createCarousel` owns the shown slide, the next / previous requests, the slide semantics (`group` or
 * `tabpanel`, `aria-roledescription="slide"`, `aria-label="2 of 5"`), the hover / focus pause and the live `aria-live` the
 * frame announces; the skin owns the frame and the control row, the indicator, the enter animation that honours reduced
 * motion, and the two gestures the primitive leaves to the host: the arrow keys on a focused slide and a touch swipe.
 *
 * The primitive hides every slide but the current one, so the track is a stack and the skin does not translate it; a page
 * that wants a scrolling strip uses its own markup. Auto-rotation is off: the primitive advances only through `tick`, which
 * needs a timer the page owns.
 */
export const Carousel = (props: CarouselProps): JSX.Element => {
  const carousel = createCarousel({
    items: props.slides.length,
    role: props.role ?? "region",
    labelledBy: props.labelledBy,
    defaultIndex: props.defaultIndex,
    get value() {
      return props.value;
    },
    get onValueChange() {
      return props.onValueChange;
    },
    // no timer: a control that starts a rotation nothing advances would lie, and a paused carousel is the honest default
    autoRotate: false,
  });

  let track: HTMLDivElement | undefined;
  /** An arrow key asked for the focus to follow the slide it showed. */
  let followFocus = false;

  /** Focus the slide that is current now: an arrow key hides the slide it was pressed on. */
  const focusCurrent = (): void => {
    track?.querySelector<HTMLElement>('[data-part="carousel-slide"][tabindex="0"]')?.focus();
  };

  // the current slide changed: once its tab stop is in place, an arrow key's focus follows it
  createEffect(
    () => carousel.current(),
    () => {
      if (followFocus) {
        followFocus = false;
        focusCurrent();
      }
    },
  );

  const onKeyDown = (event: KeyboardEvent): void => {
    if (event.defaultPrevented || event.altKey || event.ctrlKey || event.metaKey) {
      return;
    }
    const target = event.target;
    // the keys belong to the slides, not to a field or a button a slide may hold
    if (!(target instanceof HTMLElement) || !target.closest('[data-part="carousel-slide"]')) {
      return;
    }
    if (target.closest('input, textarea, select, [contenteditable="true"]') !== null) {
      return;
    }
    if (event.key === "ArrowRight") {
      event.preventDefault();
      followFocus = carousel.current() !== (carousel.current() + 1) % carousel.items;
      carousel.next();
    } else if (event.key === "ArrowLeft") {
      event.preventDefault();
      followFocus = carousel.current() !== (carousel.current() - 1 + carousel.items) % carousel.items;
      carousel.prev();
    }
  };

  // The swipe is touch-only: a mouse drag on a slide stays a selection, and the buttons are the pointer's way.
  let startX: number | undefined;
  const onPointerDown = (event: PointerEvent): void => {
    startX = event.pointerType === "touch" ? event.clientX : undefined;
  };
  const onPointerUp = (event: PointerEvent): void => {
    if (startX === undefined) {
      return;
    }
    const distance = event.clientX - startX;
    startX = undefined;
    if (Math.abs(distance) < SWIPE_THRESHOLD) {
      return;
    }
    if (distance < 0) {
      carousel.next();
    } else {
      carousel.prev();
    }
  };
  const onPointerCancel = (): void => {
    startX = undefined;
  };

  const trackProps = {
    id: carousel.prevProps["aria-controls"],
    "data-part": "carousel-track",
    onKeyDown,
    onPointerDown,
    onPointerUp,
    onPointerCancel,
    get class() {
      return trackClass;
    },
  };

  const next = merge(carousel.nextProps, {
    "data-part": "carousel-next",
    "aria-label": "Next slide",
    get class() {
      return controlClass;
    },
  });

  const prev = merge(carousel.prevProps, {
    "data-part": "carousel-prev",
    "aria-label": "Previous slide",
    get class() {
      return controlClass;
    },
  });

  return (
    <div
      {...carousel.carouselProps}
      data-part="carousel"
      aria-label={props.labelledBy === undefined ? (props.label ?? "Carousel") : undefined}
      class={css.cn(frameClass, props.class)}
    >
      <div
        {...trackProps}
        ref={(element: HTMLDivElement) => {
          track = element;
        }}
      >
        <For each={props.slides}>
          {(slide, index) => (
            <div
              {...carousel.slideProps(index())}
              data-part="carousel-slide"
              class={css.cn(slideClass, slideMotion)}
            >
              {slide}
            </div>
          )}
        </For>
      </div>
      <div data-part="carousel-bar" class={barClass}>
        <button {...prev}>
          <span aria-hidden="true">‹</span>
        </button>
        <div data-part="carousel-indicator" class={indicatorClass}>
          <For each={props.slides}>
            {(_, index) => (
              <button
                type="button"
                data-part="carousel-dot"
                aria-label={`Go to slide ${index() + 1}`}
                aria-current={carousel.current() === index() ? "true" : undefined}
                class={dotClass}
                onClick={() => carousel.selectSlide(index())}
              >
                <span
                  aria-hidden="true"
                  class={css.cn(
                    dotMarkClass,
                    carousel.current() === index() ? dotMarkActiveClass : "",
                  )}
                />
              </button>
            )}
          </For>
          <span data-part="carousel-count" class={countClass}>
            {`${carousel.current() + 1} of ${carousel.items}`}
          </span>
        </div>
        <button {...next}>
          <span aria-hidden="true">›</span>
        </button>
      </div>
      <p data-part="carousel-hint" class={hintClass}>
        {props.hint ?? DEFAULT_HINT}
      </p>
    </div>
  );
};

import { look } from "@cssints/mise-en-mode" with { type: "cssints" };
import { check, createGlobalTheme, createTokens, media } from "cssints" with { type: "cssints" };

import { darkTheme, forcedColorsTheme, lightTokens } from "./tokens.ts";

// The theme the starters are written against: one lightness scale, one hue and one chroma per
// colour family, and the semantic colours made of them. The data lives in tokens.ts, so the
// registry can compile it to a plain theme.css without the cssints plugin; this module is the
// same theme for the components and the demo page, with the contrast gate.
const t = createTokens(lightTokens);

// The dark mode is the lightness scale turned over, so every step and every colour made of it follows: the text is still
// gray-1200, it is just a light gray now. The page and the surface are the reference's own dark values, and the popover shadow
// deepens because a shadow on a dark page reads as a smudge.
createGlobalTheme(t, media("(prefers-color-scheme: dark)"), darkTheme);

// The same dark look as a scope a page can ask for: `<div data-mode="dark">` moves every token inside it, and a surface or a
// frame under it follows without a prop. It is a mise-en-mode look, so it is in the `app` layer: a host's `author` or `viewer`
// look over the same marker wins without a specificity trick, and `data-mode="dark/color"` moves the colours alone. The media
// query above stays a global theme: a look is a `data-mode` scope, and the system preference is not one.
look(t, "dark", "app", darkTheme);

// One preset, because the theme is neutral: the reference's indigo, as its two numbers. The others are in its theme.css.
createGlobalTheme(t, '[data-tint="indigo"]', {
  hue: { tint: "284.23" },
  chroma: { tint: "0.25049" },
});

// On a dense screen (200dpi and up) the targets grow: the spacing steps and the text with them, as in the reference.
createGlobalTheme(t, media("(min-resolution: 200dpi)"), {
  space: { base: "calc(0.25rem * 1.25)" },
  font: { sizeSm: "0.9375rem", size: "1.0625rem", sizeLg: "1.25rem" },
});

// Windows high contrast mode throws the theme away and paints the system's own colours; forced-colors makes that explicit,
// since a component that reads a token here gets the system colour rather than the tint.
createGlobalTheme(t, media("(forced-colors: active)"), forcedColorsTheme);

// The pairs a reader meets on every page: body text, the second level of text, and a link on a card. Both modes and every
// theme above are checked (the preset too, since it sets the tokens the link is made of), and a ratio under the floor fails
// the build. 7 for text and 4.5 for the rest are the WCAG 2.x AAA and AA floors.
check.contrast(t.color.text, t.color.page, { min: 7 }); // the tabs skin's selected label
check.contrast(t.color.muted, t.color.page, { min: 4.5 }); // its unselected label
check.contrast(t.color.link, t.color.surface, { min: 4.5 });
check.contrast(t.color.placeholder, t.color.page, { min: 4.5 });
check.contrast(t.color.onHighlight, t.color.highlight, { min: 4.5 });
// The active tab's underline is a graphic against the page: 3 is the WCAG 1.4.11 floor for non-text contrast. The dark
// mode is the closest (3.55:1 without the preset, 3.17:1 with indigo), so a lighter highlight would break it.
check.contrast(t.color.highlight, t.color.page, { min: 3 });
// The focus ring is a graphic, not text: 3 is the WCAG 1.4.11 floor for a non-text contrast.
check.contrast(t.color.focusRing, t.color.page, { min: 3 }); // the tabs skin's ring

export { t };

import { render } from "@solidjs/web";
import type { JSX } from "@solidjs/web";

import { Carousel } from "./carousel.tsx";

/** One slide of the demo: a drawing and the line a caption would say. */
export interface CarouselSlide {
  readonly title: string;
  readonly caption: string;
  /** The two ends of the slide's gradient. */
  readonly from: string;
  readonly to: string;
}

/** The gallery's five slides; the colours stand apart at a glance, so the change of slide is visible. */
export const CAROUSEL_SLIDES: ReadonlyArray<CarouselSlide> = [
  {
    title: "Dawn",
    caption: "The first slide is the one the carousel shows at mount.",
    from: "#f7c59f",
    to: "#ef8354",
  },
  {
    title: "Forest",
    caption: "Next and previous move one slide, and so do the arrow keys on a focused slide.",
    from: "#b8d8ba",
    to: "#4f7d63",
  },
  {
    title: "Ocean",
    caption: "The dots below are the indicator: a click shows that slide, the count says where it is.",
    from: "#a8d1e7",
    to: "#3a6ea5",
  },
  {
    title: "Dusk",
    caption: "The carousel is one tab stop: the shown slide takes the focus, the others are hidden.",
    from: "#c3b1e1",
    to: "#6d597a",
  },
  {
    title: "Night",
    caption: "The last slide wraps to the first with Next: the primitive never disables the control.",
    from: "#3d405b",
    to: "#1b1b2f",
  },
];

const figureStyle: JSX.CSSProperties = {
  margin: "0",
  "border-radius": "10px",
  overflow: "hidden",
  background: "#ffffff",
};

const drawingStyle = (slide: CarouselSlide): JSX.CSSProperties => ({
  display: "flex",
  "align-items": "flex-end",
  height: "200px",
  padding: "16px",
  "box-sizing": "border-box",
  background: `linear-gradient(135deg, ${slide.from}, ${slide.to})`,
});

const numeralStyle: JSX.CSSProperties = {
  color: "rgb(255 255 255 / 0.85)",
  "font-size": "48px",
  "font-weight": "700",
  "line-height": "1",
};

const captionStyle: JSX.CSSProperties = {
  margin: "0",
  padding: "16px",
  "min-height": "76px",
  "box-sizing": "border-box",
  color: "#3d3d3d",
  "font-size": "14px",
  "line-height": "1.5",
};

export interface CarouselExampleProps {
  readonly class?: string | undefined;
}

/**
 * The starter in ordinary use: five drawn slides on the neutral theme, the control row with its dots and count, and the
 * sentence that says how the keyboard and a touch screen reach the slides. A page copies this and swaps the figures for its
 * own content.
 */
export const CarouselExample = (props: CarouselExampleProps): JSX.Element => {
  const slides = CAROUSEL_SLIDES.map((slide, index) => (
    <figure style={figureStyle}>
      <div style={drawingStyle(slide)}>
        <span aria-hidden="true" style={numeralStyle}>
          {index + 1}
        </span>
      </div>
      <figcaption style={captionStyle}>{slide.caption}</figcaption>
    </figure>
  ));
  return (
    <div class={props.class} style={{ width: "100%" }}>
      <Carousel label="A gallery of five slides" slides={slides} />
    </div>
  );
};

/** What a mounted demo hands the test: where it lives and a teardown. */
export interface MountedCarousel {
  readonly root: HTMLElement;
  readonly dispose: () => void;
}

/** The demo's width, so the frame (and the slides) have the same shape in every test run. */
const DEMO_WIDTH = 480;

/**
 * Mounts the styled carousel in ordinary use at a 480 px frame. The primitive owns the shown slide, the requests and the
 * slide semantics; the fixture is the page's content.
 */
export const mountCarousel = (): MountedCarousel => {
  const root = document.createElement("div");
  root.style.width = `${DEMO_WIDTH}px`;
  document.body.append(root);
  const dispose = render(() => <CarouselExample />, root);
  return {
    root,
    dispose: () => {
      dispose();
      root.remove();
    },
  };
};

import { afterEach, describe, expect, it } from "vite-plus/test";

import { type MountedCarousel, mountCarousel } from "./carousel.fixture";

// @cssints/headless checks `createCarousel` against specs/apg/carousel.qnt and the ported APG scenarios. This file is the
// skin's oracle: it mounts the starter in a real Chromium and drives the same controls a reader does. The skin's own parts
// (the named frame, the control row, the indicator, the arrow keys and the touch swipe) are only observable through the DOM.

/** Solid applies setters on the next flush, and the enter animation starts with it: two frames settle both. */
const settle = (): Promise<void> =>
  new Promise((resolve) => requestAnimationFrame(() => requestAnimationFrame(() => resolve())));

const live: MountedCarousel[] = [];

const mounted = (): MountedCarousel => {
  const instance = mountCarousel();
  live.push(instance);
  return instance;
};

afterEach(() => {
  for (const instance of live.splice(0)) {
    instance.dispose();
  }
});

const part = <T extends HTMLElement>(root: ParentNode, name: string): T => {
  const element = root.querySelector<T>(`[data-part="${name}"]`);
  if (element === null) {
    throw new Error(`carousel: no ${name}`);
  }
  return element;
};

const frame = (root: ParentNode): HTMLElement => part(root, "carousel");
const track = (root: ParentNode): HTMLElement => part(root, "carousel-track");
const count = (root: ParentNode): HTMLElement => part(root, "carousel-count");

const slides = (root: ParentNode): HTMLElement[] => [
  ...root.querySelectorAll<HTMLElement>('[data-part="carousel-slide"]'),
];

const dots = (root: ParentNode): HTMLButtonElement[] => [
  ...root.querySelectorAll<HTMLButtonElement>('[data-part="carousel-dot"]'),
];

const shown = (root: ParentNode): HTMLElement[] =>
  slides(root).filter((slide) => !slide.hasAttribute("hidden"));

const shownIndex = (root: ParentNode): number => slides(root).indexOf(shown(root)[0] as HTMLElement);

const click = async (element: HTMLElement): Promise<void> => {
  element.click();
  await settle();
};

/** A key on a slide, as a reader's would arrive. */
const press = async (target: HTMLElement, key: string): Promise<void> => {
  target.dispatchEvent(new KeyboardEvent("keydown", { key, bubbles: true, cancelable: true }));
  await settle();
};

const swipe = async (root: ParentNode, from: number, to: number): Promise<void> => {
  const element = track(root);
  element.dispatchEvent(
    new PointerEvent("pointerdown", {
      pointerType: "touch",
      clientX: from,
      bubbles: true,
      cancelable: true,
    }),
  );
  element.dispatchEvent(
    new PointerEvent("pointerup", {
      pointerType: "touch",
      clientX: to,
      bubbles: true,
      cancelable: true,
    }),
  );
  await settle();
};

describe("Carousel", () => {
  it("is a named carousel whose slides carry the primitive's semantics", () => {
    const { root } = mounted();

    expect(frame(root).getAttribute("role")).toBe("region");
    expect(frame(root).getAttribute("aria-label")).toBe("A gallery of five slides");
    expect(frame(root).getAttribute("aria-roledescription")).toBe("carousel");
    // auto-rotation is off, so the primitive's live region is the polite one
    expect(frame(root).getAttribute("aria-live")).toBe("polite");

    expect(slides(root)).toHaveLength(5);
    expect(slides(root).map((slide) => slide.getAttribute("aria-roledescription"))).toEqual(
      Array.from({ length: 5 }, () => "slide"),
    );
    expect(slides(root).map((slide) => slide.getAttribute("aria-label"))).toEqual([
      "1 of 5",
      "2 of 5",
      "3 of 5",
      "4 of 5",
      "5 of 5",
    ]);
    expect(slides(root)[0]?.getAttribute("role")).toBe("group");
    expect(shown(root)).toHaveLength(1);
    expect(shownIndex(root)).toBe(0);
    expect(slides(root)[0]?.tabIndex).toBe(0);
    expect(slides(root)[1]?.tabIndex).toBe(-1);
  });

  it("wires the controls to the track the primitive names", () => {
    const { root } = mounted();
    const next = part<HTMLButtonElement>(root, "carousel-next");
    const prev = part<HTMLButtonElement>(root, "carousel-prev");

    expect(next.getAttribute("aria-label")).toBe("Next slide");
    expect(prev.getAttribute("aria-label")).toBe("Previous slide");
    expect(next.getAttribute("aria-controls")).toBe(track(root).id);
    expect(prev.getAttribute("aria-controls")).toBe(track(root).id);
    expect(track(root).id).not.toBe("");
  });

  it("moves the shown slide with next and previous, and the indicator follows", async () => {
    const { root } = mounted();
    const next = part<HTMLButtonElement>(root, "carousel-next");
    const prev = part<HTMLButtonElement>(root, "carousel-prev");

    expect(count(root).textContent?.trim()).toBe("1 of 5");

    await click(next);
    expect(shownIndex(root)).toBe(1);
    expect(count(root).textContent?.trim()).toBe("2 of 5");
    expect(dots(root)[1]?.getAttribute("aria-current")).toBe("true");
    expect(dots(root)[0]?.hasAttribute("aria-current")).toBe(false);

    await click(next);
    expect(shownIndex(root)).toBe(2);
    expect(count(root).textContent?.trim()).toBe("3 of 5");

    await click(prev);
    expect(shownIndex(root)).toBe(1);
    expect(count(root).textContent?.trim()).toBe("2 of 5");
  });

  it("wraps at both ends, because the primitive never disables a control", async () => {
    const { root } = mounted();
    const next = part<HTMLButtonElement>(root, "carousel-next");
    const prev = part<HTMLButtonElement>(root, "carousel-prev");

    await click(prev);
    expect(shownIndex(root)).toBe(4);
    expect(count(root).textContent?.trim()).toBe("5 of 5");

    await click(next);
    expect(shownIndex(root)).toBe(0);
    expect(count(root).textContent?.trim()).toBe("1 of 5");
  });

  it("shows a slide when its dot is clicked", async () => {
    const { root } = mounted();

    await click(dots(root)[3] as HTMLButtonElement);
    expect(shownIndex(root)).toBe(3);
    expect(count(root).textContent?.trim()).toBe("4 of 5");
    expect(dots(root)[3]?.getAttribute("aria-current")).toBe("true");
    // the dot moved the shown slide, not the focus: a pointer press on the primitive's controls does not take it
    expect(document.activeElement).not.toBe(dots(root)[3]);
  });

  it("moves with the arrow keys while a slide has the focus", async () => {
    const { root } = mounted();
    const first = slides(root)[0] as HTMLElement;
    first.focus();
    expect(document.activeElement).toBe(first);

    await press(first, "ArrowRight");
    expect(shownIndex(root)).toBe(1);
    // the slide the key was pressed on is hidden now, so the focus follows the slide that is shown
    expect(document.activeElement).toBe(slides(root)[1]);

    await press(slides(root)[1] as HTMLElement, "ArrowLeft");
    expect(shownIndex(root)).toBe(0);
    expect(document.activeElement).toBe(slides(root)[0]);

    await press(slides(root)[0] as HTMLElement, "ArrowLeft");
    expect(shownIndex(root)).toBe(4);
    expect(document.activeElement).toBe(slides(root)[4]);
  });

  it("changes slide on a touch swipe, and leaves a mouse drag alone", async () => {
    const { root } = mounted();

    await swipe(root, 320, 200);
    expect(shownIndex(root)).toBe(1);

    await swipe(root, 200, 320);
    expect(shownIndex(root)).toBe(0);

    // a mouse drag is a selection, not a gesture the carousel takes
    track(root).dispatchEvent(
      new PointerEvent("pointerdown", {
        pointerType: "mouse",
        clientX: 320,
        bubbles: true,
        cancelable: true,
      }),
    );
    track(root).dispatchEvent(
      new PointerEvent("pointerup", {
        pointerType: "mouse",
        clientX: 200,
        bubbles: true,
        cancelable: true,
      }),
    );
    await settle();
    expect(shownIndex(root)).toBe(0);
  });
});

import solid from "@solidjs/vite-plugin";
import cssints, { targets } from "cssints/vite";
import { defineConfig } from "vite-plus";
import { playwright } from "vite-plus/test/browser-playwright";

// The conformance test a starter arrives with runs in a real Chromium: the scenario walk needs a
// real DOM and Solid 2's reactivity, not a simulated one.
export default defineConfig({
  // `evaluation.inline`: a browser-mode runner inlines everything as ESM, so the plugin's own
  // evaluation server keeps the framework's packages inlined (Solid resolves its client build by
  // them) and the rest external (Node loads their CJS). Without it, a click's target resolves
  // against a second copy of Solid and the walk reads a state the page never changed.
  plugins: [
    cssints({ evaluation: { inline: ["solid-js", "@solidjs/web", "@solidjs/signals"] } }),
    solid(),
  ],
  css: { transformer: "lightningcss", lightningcss: { targets } },
  // The plugin adds `import derived from "cssints/derived"` to a client module after the dep
  // scanner has run; pre-bundling it here is what keeps that from reloading the page mid-test.
  optimizeDeps: { include: ["cssints/derived"] },
  test: {
    // a browser test has no app entry: the sheet of the modules the test imports arrives through
    // `virtual:cssints.css`, and vitest drops CSS imports unless it is told to process them
    css: true,
    // the sheet is loaded by the test's imports, not before them
    setupFiles: ["src/sheet.ts"],
    include: ["src/components/ui/**/*.browser.test.tsx"],
    browser: {
      enabled: true,
      provider: playwright(),
      headless: true,
      viewport: { width: 1280, height: 1024 },
      instances: [{ browser: "chromium" }],
      // The default waits 60 s for a worker's iframe to come up, which a busy machine (or a CI runner with a dozen other
      // jobs) misses: the run then fails as `the iframe did not become ready` with no test having run. Nothing about a
      // test gets longer; this is the browser starting.
      connectTimeout: 120_000,
      // the iframe ready timeout is read from the config's own env, not from the process that started the run
      env: { VITEST_BROWSER_IFRAME_TIMEOUT: "120000" },
    },
  },
});

// The engine's sheet for a browser test: its content is the CSS of the modules transformed so far, so it is loaded once the
// test file's imports are in (in `beforeAll`, not as a static import: vitest resolves the graph as it goes, and a sheet loaded
// first is just the `@layer` statement). A component's conformance test clicks its parts, so the sheet has to be there.
import { beforeAll } from "vite-plus/test";

beforeAll(async () => {
  await import("virtual:cssints.css");
});
